    if (taxMetric === "cumulativePct") {
      return rows.sort((a, b) => b.cumulativePct - a.cumulativePct);
    }
    return rows.sort((a, b) => b.shareOfUniversePct - a.shareOfUniversePct);
  }, [taxMetric, includeResidual]);

  const familyPie = useMemo(
    () =>
      TAX_FAMILY_SHARES.map((r) => ({
        name: r.short,
        value: r.bn,
