            </ul>
          </ChartCard>

          <ChartCard
            title="Headline anchors"
            subtitle="Numbers to keep in working memory while reading the post"
          >
            <div className="grid gap-3 sm:grid-cols-2">
              {[
                {
                  k: "Tax top-1",
                  v: `${fmtPct(HEADLINE.top1TaxSharePct)} ?? ${fmtBn(HEADLINE.top1TaxBn)}`,
                  s: HEADLINE.top1TaxLabel,
                },
                {
                  k: "Tax top-3",
                  v: `${fmtPct(HEADLINE.top3TaxSharePct)} ?? ${fmtBn(HEADLINE.top3TaxBn)}`,
                  s: HEADLINE.top3TaxLabel,
                },
                {
                  k: "Top-10 of universe",
                  v: fmtPct(HEADLINE.top10SharePct),
                  s: `${fmtBn(HEADLINE.jctTop10Bn)} of $${HEADLINE.jctUniverseTn}T`,
                },
                {
                  k: "GSE MBS stock",
                  v: fmtTn(HEADLINE.gseStockTn),
                  s: "Housing-credit off-balance lever",
                },
                {
                  k: "Trust top-1",
                  v: fmtPct(HEADLINE.top1TrustSharePct),
                  s: HEADLINE.top1TrustLabel,
                },
                {
                  k: "Off-balance top-3",
                  v: fmtPct(HEADLINE.top3OffBalanceSharePct),
                  s: "FDIC ?? GSE ?? FHA/VA",
                },
              ].map((row) => (
                <div
                  key={row.k}
                  className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-3"
                >
                  <p className="text-[11px] uppercase tracking-wide text-slate-500">
                    {row.k}
                  </p>
                  <p className="mt-1 text-lg font-bold text-slate-900">{row.v}</p>
                  <p className="text-xs text-slate-500">{row.s}</p>
                </div>
              ))}
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

