"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  LENS_COMPARE,
  OFF_BALANCE_CONCENTRATION_CURVE,
  OFF_BALANCE_SHARES,
  PLUMBING_LAYERS,
  SOURCE_NOTE,
  TAX_CONCENTRATION_CURVE,
  TAX_FAMILY_SHARES,
  TAX_LINES,
  TRUST_CONCENTRATION_CURVE,
  TRUST_FUND_SHARES,
  disclosedTaxLines,
  fmtBn,
  fmtPct,
  fmtTn,
} from "@/data/fiscal-plumbing-concentration-2026-data";

// viz-types: Lorenz area+line, ranked share bars, family pie, trust pie, leverage scatter, layer bars | layout: default

type ViewId = "tax" | "trusts" | "offbalance" | "layers";
type TaxMetric = "shareOfUniversePct" | "bn" | "cumulativePct";
type CurveLens = "tax" | "trust" | "offbalance";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";
const AMBER = "#f59e0b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function FiscalPlumbingConcentration2026Dashboard() {
  const [view, setView] = useState<ViewId>("tax");
  const [taxMetric, setTaxMetric] = useState<TaxMetric>("shareOfUniversePct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [curveLens, setCurveLens] = useState<CurveLens>("tax");
  const [includeResidual, setIncludeResidual] = useState(false);

  const curve = useMemo(() => {
    if (curveLens === "trust") return TRUST_CONCENTRATION_CURVE;
    if (curveLens === "offbalance") return OFF_BALANCE_CONCENTRATION_CURVE;
    return TAX_CONCENTRATION_CURVE;
  }, [curveLens]);

  const taxBars = useMemo(() => {
    const rows = includeResidual ? [...TAX_LINES] : disclosedTaxLines();
    if (taxMetric === "bn") return rows.sort((a, b) => b.bn - a.bn);
    if (taxMetric === "cumulativePct") {
      return rows.sort((a, b) => b.cumulativePct - a.cumulativePct);
    }
    return rows.sort((a, b) => b.shareOfUniversePct - a.shareOfUniversePct);
  }, [taxMetric, includeResidual]);

  const familyPie = useMemo(
    () =>
      TAX_FAMILY_SHARES.map((r) => ({
        name: r.short,
        value: r.bn,
        sharePct: r.sharePct,
        fill: r.fill,
      })),
    [],
  );

  const trustPie = useMemo(
    () =>
      TRUST_FUND_SHARES.map((r) => ({
        name: r.short,
        value: r.reservesTn,
        sharePct: r.sharePct,
        fill: r.fill,
        depletionYear: r.depletionYear,
      })),
    [],
  );

  const layerBars = useMemo(
    () => [...PLUMBING_LAYERS].sort((a, b) => b.bn - a.bn),
    [],
  );

  const offBalanceScatter = useMemo(
    () =>
      OFF_BALANCE_SHARES.map((r) => ({
        ...r,
        x: r.budgetVisibility,
        y: r.policyLeverage,
        z: Math.max(40, r.stockTn * 18),
      })),
    [],
  );

  const lensScatter = useMemo(
    () =>
      LENS_COMPARE.map((l) => ({
        ...l,
        x: l.top1Pct,
        y: l.top3Pct,
        z: Math.max(8, l.top3Pct / 4),
      })),
    [],
  );

  const curveStroke =
    curveLens === "tax" ? AMBER : curveLens === "trust" ? SKY : VIOLET;

  return (
    <div
      className="space-y-6"
      data-viz="fiscal-plumbing-concentration-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white shadow-sm sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300">
          Fiscal plumbing ??? concentration lens
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          Top-1 tax line holds {HEADLINE.top1TaxSharePct}% ?? Top-3 holds{" "}
          {HEADLINE.top3TaxSharePct}%
        </h2>
        <p className="mt-3 max-w-3xl text-sm leading-relaxed text-slate-300">
          Inside the{" "}
          <span className="text-amber-200">
            ${HEADLINE.jctUniverseTn}T JCT tax-expenditure universe
          </span>
          , the single largest line (pensions) is{" "}
          <span className="text-sky-300">
            {fmtPct(HEADLINE.top1TaxSharePct)}
          </span>
          ; pensions + CG/dividends + employer health clear{" "}
          <span className="text-rose-300">
            {fmtPct(HEADLINE.top3TaxSharePct)}
          </span>
          . Trust-fund reserves are far sharper: OASI alone is{" "}
          <span className="text-violet-300">
            {fmtPct(HEADLINE.top1TrustSharePct)}
          </span>
          . Off-balance credit is a two-vehicle story ??? FDIC + GSE MBS ???{" "}
          {fmtPct(HEADLINE.top2OffBalanceSharePct)}.
        </p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
            {
              label: "Top-1 tax TE",
              value: fmtPct(HEADLINE.top1TaxSharePct),
              sub: HEADLINE.top1TaxLabel,
            },
            {
              label: "Top-3 tax TE",
              value: fmtPct(HEADLINE.top3TaxSharePct),
              sub: fmtBn(HEADLINE.top3TaxBn),
            },
            {
              label: "Top-1 trust",
              value: fmtPct(HEADLINE.top1TrustSharePct),
              sub: HEADLINE.top1TrustLabel,
            },
            {
              label: "Top-2 off-balance",
              value: fmtPct(HEADLINE.top2OffBalanceSharePct),
              sub: "FDIC + GSE MBS",
            },
          ].map((k) => (
            <div
              key={k.label}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-3"
            >
              <p className="text-[11px] uppercase tracking-wide text-slate-400">
                {k.label}
              </p>
              <p className="mt-1 text-xl font-bold tabular-nums">{k.value}</p>
              <p className="text-xs text-slate-400">{k.sub}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-4">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "tax", label: "Tax expenditures" },
            { id: "trusts", label: "Trust funds" },
            { id: "offbalance", label: "Off-balance" },
            { id: "layers", label: "Layers & lenses" },
          ]}
        />
      </div>

      {view === "tax" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cumulative share vs equal split"
            subtitle="How fast the top of each plumbing distribution accumulates"
          >
            <div className="mb-3 flex flex-wrap gap-3">
              <ToggleGroup
                label="Lens"
                value={curveLens}
                onChange={setCurveLens}
                options={[
                  { id: "tax", label: "Tax TE" },
                  { id: "trust", label: "Trusts" },
                  { id: "offbalance", label: "Off-balance" },
                ]}
              />
              <ToggleGroup
                label="Equal line"
                value={showEqualLine ? "on" : "off"}
                onChange={(v) => setShowEqualLine(v === "on")}
                options={[
                  { id: "on", label: "Show" },
                  { id: "off", label: "Hide" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={curve}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "sharePct" ? "Actual cumulative" : "Equal split",
                    ]}
                  />
                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    fill={curveStroke}
                    fillOpacity={0.25}
                    stroke={curveStroke}
                    strokeWidth={2.5}
                    name="sharePct"
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      stroke={SLATE}
                      strokeDasharray="6 4"
                      strokeWidth={1.5}
                      dot={false}
                      name="equalPct"
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              {curveLens === "tax" &&
                `Top-1 ${fmtPct(HEADLINE.top1TaxSharePct)} ?? Top-3 ${fmtPct(HEADLINE.top3TaxSharePct)} of the JCT universe.`}
              {curveLens === "trust" &&
                `Top-1 ${fmtPct(HEADLINE.top1TrustSharePct)} ?? Top-3 ${fmtPct(HEADLINE.top3TrustSharePct)} of reserve stock.`}
              {curveLens === "offbalance" &&
                `Top-1 ${fmtPct(HEADLINE.top1OffBalanceSharePct)} ?? Top-3 ${fmtPct(HEADLINE.top3OffBalanceSharePct)} of off-balance stock.`}
            </p>
          </ChartCard>

          <ChartCard
            title="Tax-expenditure ladder"
            subtitle="JCT FY2026 largest lines against the $2.3T universe"
          >
            <div className="mb-3 flex flex-wrap gap-3">
              <ToggleGroup
                label="Metric"
                value={taxMetric}
                onChange={setTaxMetric}
                options={[
                  { id: "shareOfUniversePct", label: "Share of $2.3T" },
                  { id: "bn", label: "USD billions" },
                  { id: "cumulativePct", label: "Cumulative" },
                ]}
              />
              <ToggleGroup
                label="Residual"
                value={includeResidual ? "on" : "off"}
                onChange={(v) => setIncludeResidual(v === "on")}
                options={[
                  { id: "off", label: "Top-10 only" },
                  { id: "on", label: "Include rest" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={taxBars}
                  layout="vertical"
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      taxMetric === "bn" ? `$${v}B` : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={88}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      taxMetric === "bn"
                        ? fmtBn(Number(v))
                        : `${Number(v).toFixed(1)}%`,
                      taxMetric === "bn"
                        ? "Score"
                        : taxMetric === "cumulativePct"
                          ? "Cumulative"
                          : "Share of universe",
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Bar
                    dataKey={
                      taxMetric === "bn"
                        ? "bn"
                        : taxMetric === "cumulativePct"
                          ? "cumulativePct"
                          : "shareOfUniversePct"
                    }
                    radius={[0, 4, 4, 0]}
                  >
                    {taxBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Family mix inside the top-10"
            subtitle="Retirement, capital, and health dominate the disclosed ladder"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={familyPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {familyPie.map((r) => (
                      <Cell key={r.name} fill={r.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v, _n, item) => [
                      `${fmtBn(Number(v))} (${fmtPct(item?.payload?.sharePct ?? 0)})`,
                      item?.payload?.name ?? "Family",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">
              {TAX_FAMILY_SHARES.slice(0, 4).map((f) => (
                <li key={f.short}>
                  <span className="font-medium text-slate-700">{f.short}</span>
                  : {fmtPct(f.sharePct)}
                </li>
              ))}
            </ul>
          </ChartCard>

          <ChartCard
            title="Top-1 vs top-3 across lenses"
            subtitle="Trust reserves concentrate hardest; tax lines are flatter but still top-heavy"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 4, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Top-1"
                    domain={[0, 90]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-1 share",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Top-3"
                    domain={[30, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-3",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 280]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "x" ? "Top-1" : name === "y" ? "Top-3" : name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.short ?? ""
                    }
                  />
                  <Scatter data={lensScatter}>
                    {lensScatter.map((p) => (
                      <Cell key={p.short} fill={p.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "trusts" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Reserve stock concentration"
            subtitle="OASI dominates the trust-fund balance sheet"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={trustPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={105}
                    paddingAngle={2}
                  >
                    {trustPie.map((r) => (
                      <Cell key={r.name} fill={r.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v, _n, item) => [
                      `${fmtTn(Number(v))} (${fmtPct(item?.payload?.sharePct ?? 0)})`,
                      item?.payload?.name ?? "Fund",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Top-1 {fmtPct(HEADLINE.top1TrustSharePct)} (OASI) ?? Top-3{" "}
              {fmtPct(HEADLINE.top3TrustSharePct)}. Combined OASDI omitted to
              avoid double-counting.
            </p>
          </ChartCard>

          <ChartCard
            title="Reserves ladder with depletion clocks"
            subtitle="Exhausting funds carry the policy urgency; SMI is premium-financed"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={TRUST_FUND_SHARES}
                  layout="vertical"
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}T`}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={48}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtTn(Number(v)), "Reserves"]}
                    labelFormatter={(_, payload) => {
                      const row = payload?.[0]?.payload;
                      if (!row) return "";
                      const clock = row.depletionYear
                        ? ` ?? depletes ~${row.depletionYear}`
                        : " ?? premium-financed";
                      return `${row.label}${clock}`;
                    }}
                  />
                  <Bar dataKey="reservesTn" radius={[0, 4, 4, 0]}>
                    {TRUST_FUND_SHARES.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Trust concentration curve"
            subtitle="Equal-split diagonal vs actual cumulative reserve share"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Equal line"
                value={showEqualLine ? "on" : "off"}
                onChange={(v) => setShowEqualLine(v === "on")}
                options={[
                  { id: "on", label: "Show" },
                  { id: "off", label: "Hide" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={TRUST_CONCENTRATION_CURVE}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "sharePct" ? "Actual" : "Equal",
                    ]}
                  />
                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    fill={SKY}
                    fillOpacity={0.25}
                    stroke={SKY}
                    strokeWidth={2.5}
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      stroke={SLATE}
                      strokeDasharray="6 4"
                      strokeWidth={1.5}
                      dot={false}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Share of reserve stock"
            subtitle="OASI is the balance-sheet giant; HI and DI are small but policy-critical"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={TRUST_FUND_SHARES}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share"]}
                  />
